/**
 * The reader hubs (Daily Teaching System, Part 8.2): /<locale>/readers, /<locale>/readers/set-<n>,
 * /<locale>/readers/level-<a|b|c>. English only for now (every language gets its own books, PART-8-DESIGN.md §1).
 *
 * The pages render two files and nothing else:
 *
 *   content/readers/hubs.<loc>.json   GENERATED by scripts/readers/build-hubs.js from the books, the reading scope and
 *                                     the list of live deck pages: per set and per level the books whose mini-book page
 *                                     is live, with the slugs of their pages and the meta title and description
 *   content/readers/ui.<loc>.json     the pages' own strings
 *
 * A set or level has a page of its own only when it holds at least `minBooks` books (`hasPage`); one with fewer is
 * listed on the index only. The single books stay noindex deck pages under these hubs (PLAN.md §5 rule 3).
 * Checked by scripts/readers/gate-hubs.js.
 */
import { deckAssets } from '@/lib/seo/landing-content';
import type { TeachNav } from '@/lib/category-nav-data';

/** the languages that have reader hubs */
export const READER_HUB_LOCALES = ['en'] as const;

export interface ReaderPages { book: string; color: string | null; talk: string | null }
export interface ReaderBook {
  id: string;
  title: string;
  pages: ReaderPages;
  /** decodable books: the teacher note's first line ("New in this book: …") */
  line?: string | null;
  /** picture readers: the words the pictures carry and the new words read together first */
  pictureWords?: string[];
  newWords?: string[];
  /** picture readers: the cover picture (a picture that is in the book), for the homepage's Reading Room */
  cover?: { theme: string; noun: string } | null;
}
export interface ReaderSound { spelling: string; example?: string }
export interface ReaderSet {
  n: number;
  slug: string;
  hasPage: boolean;
  skill: string;
  sounds: ReaderSound[];
  heart: string[];
  blends: boolean;
  /** the sets before this one with their spellings, from the reading scope */
  before: { n: number; sounds: ReaderSound[] }[];
  metaTitle: string;
  metaDescription: string;
  books: ReaderBook[];
}
export interface ReaderLevel {
  level: 'A' | 'B' | 'C';
  slug: string;
  hasPage: boolean;
  metaTitle: string;
  metaDescription: string;
  books: ReaderBook[];
}
export interface ReaderHubs {
  locale: string;
  minBooks: number;
  index: { metaTitle: string; metaDescription: string };
  sets: ReaderSet[];
  levels: ReaderLevel[];
}
export type ReaderUi = Record<string, string>;
export type ReaderGroup = { kind: 'set'; set: ReaderSet } | { kind: 'level'; level: ReaderLevel };

const cache = new Map<string, unknown>();
async function load<T>(key: string, importer: () => Promise<{ default: unknown }>): Promise<T | null> {
  if (cache.has(key)) return cache.get(key) as T;
  try {
    const mod = await importer();
    cache.set(key, mod.default);
    return mod.default as T;
  } catch {
    cache.set(key, null);
    return null;
  }
}

const isHubLocale = (locale: string) => (READER_HUB_LOCALES as readonly string[]).includes(locale);

/** the hubs of a language, or null when it has none (no file, or no book with a live mini-book page) */
export async function getReaderHubs(locale: string): Promise<ReaderHubs | null> {
  if (!isHubLocale(locale)) return null;
  const hubs = await load<ReaderHubs>(`hubs.${locale}`, () => import(`@/content/readers/hubs.${locale}.json`));
  if (!hubs || hubs.sets.length + hubs.levels.length === 0) return null;
  return hubs;
}
export async function getReaderUi(locale: string): Promise<ReaderUi | null> {
  if (!isHubLocale(locale)) return null;
  return load<ReaderUi>(`ui.${locale}`, () => import(`@/content/readers/ui.${locale}.json`));
}

/** a set or level PAGE by its slug ("set-3", "level-a"); null when it does not exist or holds too few books */
export function findReaderGroup(hubs: ReaderHubs, slug: string): ReaderGroup | null {
  const set = hubs.sets.find((s) => s.slug === slug && s.hasPage);
  if (set) return { kind: 'set', set };
  const level = hubs.levels.find((l) => l.slug === slug && l.hasPage);
  return level ? { kind: 'level', level } : null;
}

/** every page of the hubs in order: the index, then the sets, then the levels (for the sitemap and the gate) */
export function readerHubPaths(hubs: ReaderHubs): string[] {
  return [
    'readers',
    ...hubs.sets.filter((s) => s.hasPage).map((s) => `readers/${s.slug}`),
    ...hubs.levels.filter((l) => l.hasPage).map((l) => `readers/${l.slug}`),
  ];
}

/** where a page of the hubs links for a book that a unit's lesson hands out: its set or level page, else the index */
export async function readerHubHrefForPage(locale: string, deckSlug: string): Promise<{ href: string; set?: number; level?: string } | null> {
  const hubs = await getReaderHubs(locale);
  if (!hubs) return null;
  const has = (b: ReaderBook) => b.pages.book === deckSlug || b.pages.color === deckSlug || b.pages.talk === deckSlug;
  const set = hubs.sets.find((s) => s.books.some(has));
  if (set) return set.hasPage ? { href: `/${locale}/readers/${set.slug}`, set: set.n } : { href: `/${locale}/readers` };
  const level = hubs.levels.find((l) => l.books.some(has));
  if (level) return level.hasPage ? { href: `/${locale}/readers/${level.slug}`, level: level.level } : { href: `/${locale}/readers` };
  return null;
}

/** The header entry "Readers" (2026-11-22): one link per set and level that has a page, "All readers" at the foot.
 *  null in a language without reader hubs, and when anything fails (the menu never falls with it). */
export async function readersNav(locale: string): Promise<TeachNav | null> {
  try {
    const [hubs, ui] = await Promise.all([getReaderHubs(locale), getReaderUi(locale)]);
    if (!hubs || !ui || !ui.crumb || !ui.navAll) return null;
    const items = [
      ...hubs.sets.filter((s) => s.hasPage).map((s) => ({ href: `/${locale}/readers/${s.slug}`, label: fillReader(ui.setHeading, { n: s.n, skill: s.skill }) })),
      ...hubs.levels.filter((l) => l.hasPage).map((l) => ({ href: `/${locale}/readers/${l.slug}`, label: ui.kindPictureTitle + ' · ' + fillReader(ui.levelHeading, { level: l.level }) })),
    ];
    if (!items.length) return null;
    return { label: ui.crumb, items, browseAllHref: `/${locale}/readers`, browseAllLabel: ui.navAll };
  } catch {
    return null;
  }
}

/** a deck page (nginx, trailing slash) and its thumbnail */
export const readerDeckHref = (locale: string, slug: string) => `/${locale}/decks/${slug}/`;
export const readerThumb = (locale: string, slug: string) => deckAssets(locale, slug).thumbnail;

/** "m, s, a, t, p" or "e, s as in is": the spellings of a set as the pages name them */
export const soundsText = (sounds: ReaderSound[], ui: ReaderUi) => sounds.map((s) => (s.example ? fillReader(ui.soundExample, { spelling: s.spelling, word: s.example }) : s.spelling)).join(', ');
export const fillReader = (s: string, v: Record<string, string | number>) => s.replace(/\{(\w+)\}/g, (_, k) => String(v[k] ?? `{${k}}`));
export const bookCount = (hubs: ReaderHubs) => hubs.sets.reduce((n, s) => n + s.books.length, 0) + hubs.levels.reduce((n, l) => n + l.books.length, 0);
